const s="https://wdd330-backend.onrender.com/";async function a(o){if(o.ok)return o.json();{const t=await o.json();console.log("Server error response:",t);const e=Object.values(t)[0];throw new Error(e)}}class d{async getData(t){const e=await fetch(`${s}products/search/${encodeURIComponent(t)}`);return(await a(e)).Result}async findProductById(t){const e=await fetch(`${s}product/${t}`);return(await a(e)).Result}async checkout(t){const e={method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)},n=await fetch(`${s}checkout`,e);return a(n)}async getProductsByCount(t=4){const e=await this.getData("tents");return["880RR","985RF","985PR","344YJ"].map(r=>e.find(c=>c.Id===r)).filter(Boolean).slice(0,t)}}export{d as E};
